Object.assign(I18N.DICT.pt.T, {"rq": ["Tubarão", "Nada em linha reta (cima, baixo, esquerda, direita) até 3 casas; captura ao chegar num inimigo."], "mz": ["Água-viva", "Dá 1 passo na diagonal, ou ferroa sem se mover um inimigo encostado nela em linha reta (cima, baixo, esquerda, direita)."], "pv": ["Polvo", "Seus tentáculos agarram um inimigo a 2 ou 3 casas (nas 8 direções, por cima de tudo) e o trazem encostado nele. Nem deuses nem chefes."], "sr": ["Sereia", "Seu canto empurra uma casa todos os inimigos encostados nela; os empurrados para fora do mapa ou num buraco morrem."], "bl": ["Leviatã", "Chefe, 4 pontos de vida. A cada dois turnos mergulha (não pode ser atingido) e marca em vermelho a casa do seu guarda ou soldado mais valioso; no turno seguinte surge por baixo e o devora."], "bm": ["Senhor das marés", "Chefe, 4 pontos de vida. A cada dois turnos, a maré empurra todas as suas unidades uma casa rumo ao seu lado."], "bo": ["Grande Coral", "Chefe, 5 pontos de vida. No fim de cada turno do seu lado, cresce coral (uma casa bloqueada) encostado nele ou no seu coral, na sua direção (no máximo 6). A cada 3 turnos recupera 1 ponto de vida."], "bj": ["Água-viva gigante", "Chefe, 3 pontos de vida. A cada dois turnos, um raio atinge sua unidade mais próxima dela (a 3 casas ou menos) e salta para uma de suas unidades encostada nessa."], "bx": ["Deus caído", "Chefe final, em 2 fases. Primeiro (3 pontos de vida) chama um lacaio a cada turno e esmaga uma unidade encostada nele a cada dois turnos. Depois se levanta (4 pontos de vida): avança até você e cospe fogo em linha a cada dois turnos."], "om": ["Mãe das sombras", "Faz surgir uma Sombra (um soldado das sombras da reserva comum) numa casa vazia encostada numa de suas unidades."], "of": ["Ceifador", "Mata um inimigo (não um deus) encostado numa de suas unidades."], "oe": ["Eclipse", "Mergulha o mapa na escuridão: no próximo turno, o adversário não pode posicionar nem ativar unidades."], "ou": ["Devorador de almas", "Sacrifica uma de suas unidades encostadas nele (não um deus): você ganha 50 de mana."], "oa": ["Assassino", "Dá 1 passo para uma casa vazia, ou salta 2 casas (em linha reta ou na diagonal, por cima de tudo); captura ao chegar num inimigo."], "ob": ["Bruma", "Teletransporta-se para uma casa vazia a 3 casas ou menos, ou para um inimigo a 2 casas ou menos para capturá-lo."], "oc": ["Corvo", "Voa na diagonal até 3 casas por cima de tudo; captura ao chegar num inimigo."], "ol": ["Lâmina", "Avança 2 casas em linha reta (cima, baixo, esquerda, direita) e mata os inimigos que atravessa."], "ox": ["Morcego", "Voa 2 casas (em linha reta ou na diagonal) por cima de tudo; captura ao chegar num inimigo."], "os": ["Sombra", "Soldado das sombras: dá 1 passo reto (até para trás) para uma casa vazia; captura na diagonal para a frente."], "bv": ["Coração de lava", "Chefe, 4 pontos de vida. A cada dois turnos marca em vermelho a casa do seu guarda ou soldado mais valioso; no turno seguinte a lava jorra ali: se ele ainda estiver em cima, morre."]});
