Object.assign(I18N.DICT.pt.T, {"sa": ["Arcanjo", "Chefe da Luz, 4 pontos de vida. A cada dois turnos, sua luz cega todas as suas unidades na linha e na coluna dele: você não pode ativá-las no seu próximo turno."], "sp": ["Paladino", "Chefe da Luz, 3 pontos de vida. Enquanto 2 unidades dele estiverem encostadas nele, elas o protegem: seus golpes não fazem nada. Mate os guardas dele primeiro! Ele avança na sua direção a cada dois turnos (às vezes deixando os guardas para trás) e golpeia uma unidade encostada nele a cada 4 turnos."], "sl": ["Farol", "Chefe da Luz, 2 pontos de vida. Não se move, mas sua luz paralisa seus guardas e soldados: os que estão a 2 casas ou menos não podem ser ativados (seus deuses podem). Acerte-o de longe! A cada 4 turnos, chama um capanga."], "sg": ["Golem de cristal", "Chefe da Luz, 2 pontos de vida. Seu cristal reflete tiros e feitiços: só golpes corpo a corpo o ferem. A cada 4 turnos, esmaga uma unidade encostada nele."]});
