Object.assign(I18N.DICT.pt.T, {"na": ["Possessão", "Toma o controle de um soldado ou guarda inimigo encostado numa unidade sua: ele passa para o seu lado (conta como perdido para o adversário)."], "nb": ["Maldição", "Amaldiçoa um inimigo (não um deus) em qualquer lugar do mapa: se ainda estiver na mesma casa no fim do próximo turno do seu lado, ele morre."], "nc": ["Passagem", "Faz uma unidade sua (não um deus) passar pelas sombras: ela reaparece numa casa vazia encostada noutra unidade sua."], "nd": ["Ladrão de almas", "Rouba até 30 de mana do adversário."], "ne": ["Uivo", "Todos os inimigos (não os deuses) na sua metade do mapa recuam uma casa para o lado deles, se a casa estiver livre."], "nf": ["Chamado dos mortos", "Traz 2 Sombras (soldados das sombras) para a sua reserva, mais 1 por guarda que você perdeu (no máximo 4)."], "ng": ["Grilhão", "Acorrenta uma unidade inimiga (até um deus): ela não pode ser ativada nos 2 próximos turnos do seu lado."], "nh": ["Portão das sombras", "Abre um portão: um guarda ou soldado seu aparece numa casa vazia da zona de posicionamento adversária."], "ni": ["Praga", "Todos os soldados inimigos encostados em pelo menos 2 unidades suas morrem."], "nj": ["Mortalha", "Cobre uma unidade sua e as suas unidades encostadas nela: nada pode matá-las até o seu próximo turno."], "nk": ["Maré negra", "Todas as suas Sombras (soldados das sombras) avançam uma casa em direção ao adversário, se a casa estiver livre."], "n1": ["Fantasma", "Atravessa tudo: pousa numa casa vazia a 3 casas ou menos. Onde ele chega, os soldados inimigos encostados morrem de medo e os guardas inimigos encostados não podem ser ativados no próximo turno deles."], "n2": ["Carniçal", "Dá 1 passo em qualquer direção; captura ao chegar num inimigo. Depois de uma captura, pode dar mais um passo (no máximo 3)."], "n3": ["Vampiro", "Dá 1 passo para uma casa vazia (8 direções), ou morde sem se mover um inimigo a 1 ou 2 casas em linha reta ou na diagonal, por cima de tudo (não um deus): o inimigo morre e você ganha 20 de mana."], "n4": ["Aranha", "Dá 1 passo reto para uma casa vazia, ou lança sua teia na 1.ª unidade inimiga em linha reta a 4 casas ou menos: um soldado morre, um guarda ou deus não pode ser ativado por 2 turnos do seu lado."], "n5": ["Poltergeist", "Dá 1 passo reto para uma casa vazia, ou agarra um inimigo a 1 ou 2 casas em linha reta ou na diagonal (não um deus) e o arremessa 2 casas adiante: se cair fora do mapa, num buraco ou sobre uma unidade, ele morre."], "n6": ["Serpente", "Rasteja até 3 passos retos (cima, baixo, esquerda, direita), virando como quiser, por casas vazias; captura ao chegar num inimigo."], "n7": ["Lobisomem", "Dá 1 passo em qualquer direção (captura ao chegar num inimigo). Se estiver encostado em 2 inimigos ou mais, pode entrar em fúria: todos os inimigos encostados nele morrem (não os deuses)."], "n8": ["Larva", "Dá 1 passo reto para uma casa vazia, ou captura na diagonal. Quando morre, 2 Sombras nascem ao redor dela."], "n9": ["Demônio", "Dá 1 passo em qualquer direção (captura ao chegar num inimigo), ou surge numa casa vazia encostada num deus inimigo."], "nl": ["Esqueleto", "Dá 1 passo reto (captura ao chegar num inimigo), ou arremessa um osso sem se mover num inimigo a 2 ou 3 casas em linha reta (não um deus). Quando morre, levanta-se como Sombra logo ao lado."], "nm": ["Reflexo", "Dá 1 passo reto para uma casa vazia, ou salta para o seu reflexo: a casa simétrica na mesma linha, do outro lado (esquerda ↔ direita); ali captura um inimigo, não um deus."], "nn": ["Carrasco", "Dá 1 passo para uma casa vazia (8 direções), ou executa sem se mover um inimigo encostado nele (não um deus) que também esteja encostado noutra unidade sua."], "no": ["Rastejante", "Rasteja em linha reta em direção ao adversário, até 4 casas, por casas vazias; captura ao chegar num inimigo."]});
